/*---
description: Locale casing selects language behavior through canonical and extended locale tags
features: [ts-unicode-locale-case, ts-unicode-sequences, ts-strings, ts-arrays, ts-tuples, ts-iteration]
---*/
// Generated by tooling/unicode-cases/locale-case.ts; expected values are from Node.
// Oracle: Unicode 17.0; ICU 78.3.
// docs/foundations/unicode.md: locale-sensitive casing and Staying identical to node.
const input = "\u0049\u0069\u0301\u03ac";
const rows: [string, string, string][] = [
  ["\u0054\u0052", "\u0131\u0069\u0301\u03ac", "\u0049\u0130\u0301\u0386"],
  ["\u0074\u0072\u002d\u004c\u0061\u0074\u006e\u002d\u0054\u0052\u002d\u0075\u002d\u0063\u006f\u002d\u0073\u0065\u0061\u0072\u0063\u0068", "\u0131\u0069\u0301\u03ac", "\u0049\u0130\u0301\u0386"],
  ["\u0061\u007a\u002d\u0043\u0079\u0072\u006c\u002d\u0041\u005a", "\u0131\u0069\u0301\u03ac", "\u0049\u0130\u0301\u0386"],
  ["\u006c\u0074\u002d\u004c\u0054", "\u0069\u0069\u0301\u03ac", "\u0049\u0049\u0301\u0386"],
  ["\u0065\u006c\u002d\u0047\u0052", "\u0069\u0069\u0301\u03ac", "\u0049\u0049\u0301\u0391"],
];
for (const [locale, lower, upper] of rows) {
  assert.sameValue(input.toLocaleLowerCase(locale), lower);
  assert.sameValue(input.toLocaleUpperCase(locale), upper);
}
